create view public.public_marketplace_stores with(security_invoker=true) as select s.id,s.name,s.username,s.description,s.public_city,s.public_area,s.verification_status from public.stores s where s.store_status='active' and s.verification_status='verified';
create view public.public_marketplace_products with(security_invoker=true) as select p.id,p.store_id,s.name as store_name,s.username as store_username,p.name,p.description,p.brand,p.base_unit,p.minimum_quantity,v.id as variant_id,v.variant_name,v.sale_unit,v.online_price,v.discount_price,v.stock_quantity from public.products p join public.stores s on s.id=p.store_id join public.product_variants v on v.product_id=p.id where p.status='published' and s.store_status='active' and s.verification_status='verified' and v.is_active=true and v.online_price is not null;
revoke all on public.public_marketplace_stores from anon,authenticated; revoke all on public.public_marketplace_products from anon,authenticated;
grant select on public.public_marketplace_stores to anon,authenticated; grant select on public.public_marketplace_products to anon,authenticated;